#!/usr/bin/env node

/**
 * Generic Slack Web API caller (dependency-free, native fetch, Node 18+).
 *
 * Usage:
 *   SLACK_TOKEN=xoxb-... node slack_api.cjs <method> ['<json-args>']
 *
 * Examples:
 *   node slack_api.cjs chat.postMessage '{"channel":"C123","text":"hi"}'
 *   node slack_api.cjs conversations.history '{"channel":"C123","limit":10}'
 *
 * Prints a clean "Success:"/"Failure:" line plus truncated JSON so output
 * stays LLM-friendly. Exits 0 on success, 1 on error.
 */

const API_BASE = 'https://slack.com/api';
const MAX_OUTPUT = 4000;

function getToken() {
  return process.env.SLACK_TOKEN || process.env.SLACK_BOT_TOKEN || '';
}

async function callSlack(method, args = {}, token = getToken()) {
  if (!token) {
    throw new Error(
      'No Slack token found. Set SLACK_TOKEN (or SLACK_BOT_TOKEN) in the environment.',
    );
  }
  const res = await fetch(`${API_BASE}/${method}`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${token}`,
      'Content-Type': 'application/json; charset=utf-8',
    },
    body: JSON.stringify(args),
  });
  if (!res.ok) {
    throw new Error(`Slack API returned HTTP ${res.status} for ${method}`);
  }
  const data = await res.json();
  if (!data.ok) {
    const err = new Error(`Slack API error: ${data.error || 'unknown'}`);
    err.slackError = data.error || 'unknown';
    err.data = data;
    throw err;
  }
  return data;
}

function truncate(text, max = MAX_OUTPUT) {
  if (text.length <= max) return text;
  return `${text.slice(0, max)}\n... [truncated ${text.length - max} chars]`;
}

async function main() {
  const args = process.argv.slice(2);
  if (args.length < 1) {
    console.error(
      'Usage: SLACK_TOKEN=xoxb-... node slack_api.cjs <method> [jsonArgs]',
    );
    console.error(
      'Example: node slack_api.cjs chat.postMessage \'{"channel":"C123","text":"hi"}\'',
    );
    process.exit(1);
  }
  const method = args[0];
  let payload = {};
  if (args[1]) {
    try {
      payload = JSON.parse(args[1]);
    } catch (err) {
      console.error(`Failure: jsonArgs must be valid JSON: ${err.message}`);
      process.exit(1);
    }
  }
  try {
    const data = await callSlack(method, payload);
    process.stdout.write(
      `Success: ${method}\n${truncate(JSON.stringify(data, null, 2))}\n`,
    );
  } catch (err) {
    if (err.slackError) {
      process.stderr.write(`Failure: ${err.slackError}\n`);
      const msgs =
        err.data && err.data.response_metadata && err.data.response_metadata.messages;
      if (msgs && msgs.length) process.stderr.write(`Details: ${msgs.join('; ')}\n`);
    } else {
      process.stderr.write(`Failure: ${err.message}\n`);
    }
    process.exit(1);
  }
}

module.exports = { callSlack, getToken, truncate };

if (require.main === module) {
  main();
}

#!/usr/bin/env node

/**
 * Send a Slack message (or reply in a thread).
 *
 * Usage:
 *   SLACK_TOKEN=xoxb-... node post_message.cjs <channel> "<text>" \
 *     [--thread_ts <ts>] [--blocks '<json>'] [--username <name>] [--icon_emoji <emoji>]
 *
 * Channel: ID (C123...) or name (#general). For threads pass the parent ts.
 */

const { callSlack } = require('./slack_api.cjs');

async function main() {
  const args = process.argv.slice(2);
  if (args.length < 2) {
    console.error(
      'Usage: node post_message.cjs <channel> "<text>" [--thread_ts <ts>] [--blocks <json>] [--username <name>] [--icon_emoji <emoji>]',
    );
    process.exit(1);
  }

  const channel = args[0];
  const text = args[1];
  const payload = { channel, text };

  for (let i = 2; i < args.length; i++) {
    const flag = args[i];
    const value = args[i + 1];
    if (value === undefined) {
      console.error(`Failure: missing value for ${flag}`);
      process.exit(1);
    }
    if (flag === '--thread_ts') {
      payload.thread_ts = value;
    } else if (flag === '--username') {
      payload.username = value;
    } else if (flag === '--icon_emoji') {
      payload.icon_emoji = value;
    } else if (flag === '--blocks') {
      try {
        payload.blocks = JSON.parse(value);
      } catch (err) {
        console.error(`Failure: --blocks must be valid JSON: ${err.message}`);
        process.exit(1);
      }
    } else {
      console.error(`Failure: unknown option ${flag}`);
      process.exit(1);
    }
    i++;
  }

  try {
    const data = await callSlack('chat.postMessage', payload);
    const thread = (data.message && data.message.thread_ts) || data.thread_ts || '';
    process.stdout.write(
      `Success: message posted to ${channel} (ts=${data.ts})${thread ? `, thread_ts=${thread}` : ''}\n`,
    );
  } catch (err) {
    process.stderr.write(`Failure: ${err.slackError || err.message}\n`);
    process.exit(1);
  }
}

main();

#!/usr/bin/env node

/**
 * List Slack channels (public by default).
 *
 * Usage:
 *   SLACK_TOKEN=xoxb-... node list_channels.cjs \
 *     [--limit <n>] [--include-archived] [--cursor <cursor>]
 *
 * Prints id, #name, member count, and topic. If more results exist, prints the
 * cursor to pass with --cursor for the next page.
 */

const { callSlack } = require('./slack_api.cjs');

async function main() {
  const args = process.argv.slice(2);
  const opts = { limit: 100, types: 'public_channel', exclude_archived: true };

  for (let i = 0; i < args.length; i++) {
    const flag = args[i];
    const value = args[i + 1];
    if (flag === '--limit') {
      opts.limit = parseInt(value, 10);
      if (Number.isNaN(opts.limit) || opts.limit < 1 || opts.limit > 200) {
        console.error('Failure: --limit must be an integer between 1 and 200');
        process.exit(1);
      }
      i++;
    } else if (flag === '--cursor') {
      opts.cursor = value;
      i++;
    } else if (flag === '--include-archived') {
      opts.types = 'public_channel,private_channel';
      opts.exclude_archived = false;
    } else {
      console.error(`Failure: unknown option ${flag}`);
      process.exit(1);
    }
  }

  try {
    const payload = { types: opts.types, limit: opts.limit, exclude_archived: opts.exclude_archived };
    if (opts.cursor) payload.cursor = opts.cursor;
    const data = await callSlack('conversations.list', payload);
    const channels = data.channels || [];
    if (channels.length === 0) {
      process.stdout.write('Success: no channels found.\n');
      return;
    }
    const lines = channels.map((c) => {
      const flags = [c.is_archived ? 'archived' : '', c.is_private ? 'private' : '']
        .filter(Boolean)
        .join(',');
      const topic =
        c.topic && c.topic.value
          ? ` — ${c.topic.value.replace(/\s+/g, ' ').slice(0, 80)}`
          : '';
      return `- ${c.id}  #${c.name}${flags ? ` [${flags}]` : ''} (members=${c.num_members ?? '?'})${topic}`;
    });
    const next = data.response_metadata && data.response_metadata.next_cursor;
    process.stdout.write(
      `Success: ${channels.length} channel(s)${next ? ` — more available, pass --cursor "${next}"` : ''}\n${lines.join('\n')}\n`,
    );
  } catch (err) {
    process.stderr.write(`Failure: ${err.slackError || err.message}\n`);
    process.exit(1);
  }
}

main();

#!/usr/bin/env node

/**
 * Fetch recent messages from a Slack channel (newest first).
 *
 * Usage:
 *   SLACK_TOKEN=xoxb-... node fetch_history.cjs <channel> \
 *     [--limit <n>] [--oldest <ts>] [--latest <ts>] [--inclusive] [--cursor <cursor>]
 *
 * Timestamps are float epoch seconds, e.g. 1710000000.123456.
 */

const { callSlack } = require('./slack_api.cjs');

async function main() {
  const args = process.argv.slice(2);
  if (args.length < 1) {
    console.error(
      'Usage: node fetch_history.cjs <channel> [--limit <n>] [--oldest <ts>] [--latest <ts>] [--inclusive] [--cursor <cursor>]',
    );
    process.exit(1);
  }

  const channel = args[0];
  const payload = { channel };

  for (let i = 1; i < args.length; i++) {
    const flag = args[i];
    const value = args[i + 1];
    if (flag === '--limit') {
      payload.limit = parseInt(value, 10);
      if (Number.isNaN(payload.limit) || payload.limit < 1 || payload.limit > 200) {
        console.error('Failure: --limit must be an integer between 1 and 200');
        process.exit(1);
      }
      i++;
    } else if (flag === '--oldest') {
      payload.oldest = value;
      i++;
    } else if (flag === '--latest') {
      payload.latest = value;
      i++;
    } else if (flag === '--cursor') {
      payload.cursor = value;
      i++;
    } else if (flag === '--inclusive') {
      payload.inclusive = true;
    } else {
      console.error(`Failure: unknown option ${flag}`);
      process.exit(1);
    }
  }

  try {
    const data = await callSlack('conversations.history', payload);
    const messages = data.messages || [];
    if (messages.length === 0) {
      process.stdout.write('Success: no messages found.\n');
      return;
    }
    const lines = messages.map((m) => {
      const sender = m.user ? `<@${m.user}>` : m.bot_id ? `bot:${m.bot_id}` : '?';
      const text = m.text ? m.text.replace(/\s+/g, ' ').slice(0, 200) : '(no text)';
      const thread = m.thread_ts && m.thread_ts !== m.ts ? ` [thread parent ${m.thread_ts}]` : '';
      const replies = m.reply_count ? ` [${m.reply_count} replies]` : '';
      return `- ${m.ts} ${sender} ${text}${thread}${replies}`;
    });
    const next = data.response_metadata && data.response_metadata.next_cursor;
    process.stdout.write(
      `Success: ${messages.length} message(s)${next ? ` — more available, pass --cursor "${next}"` : ''}\n${lines.join('\n')}\n`,
    );
  } catch (err) {
    process.stderr.write(`Failure: ${err.slackError || err.message}\n`);
    process.exit(1);
  }
}

main();

#!/usr/bin/env node

/**
 * Upload a file to a Slack channel (files.uploadV2 flow).
 *
 * Usage:
 *   SLACK_TOKEN=xoxb-... node upload_file.cjs <channel> <filepath> \
 *     [--comment "<text>"] [--title "<title>"] [--filename <name>]
 *
 * Implements: files.getUploadURLExternal -> POST bytes to upload_url ->
 * files.completeUploadExternal -> files.info (permalink).
 */

const fs = require('node:fs');
const path = require('node:path');
const { callSlack, getToken } = require('./slack_api.cjs');

async function uploadFile({ channel, filePath, comment, title, filename }) {
  const token = getToken();
  if (!token) {
    throw new Error(
      'No Slack token found. Set SLACK_TOKEN (or SLACK_BOT_TOKEN) in the environment.',
    );
  }
  const buf = fs.readFileSync(filePath);
  const name = filename || path.basename(filePath);

  // 1. Request an upload URL
  const init = await callSlack(
    'files.getUploadURLExternal',
    { filename: name, length: buf.length },
    token,
  );

  // 2. Push the bytes to the CDN upload_url
  const put = await fetch(init.upload_url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/octet-stream' },
    body: new Blob([buf]),
  });
  if (!put.ok) {
    throw new Error(`Upload to Slack CDN failed with HTTP ${put.status}`);
  }

  // 3. Complete the upload, sharing it to the channel
  const files = [{ id: init.file_id }];
  if (title) files[0].title = title;
  const done = await callSlack(
    'files.completeUploadExternal',
    {
      files,
      ...(channel ? { channel_id: channel } : {}),
      ...(comment ? { initial_comment: comment } : {}),
    },
    token,
  );

  // 4. Fetch permalink (nice-to-have; do not fail the upload if it errors)
  const file = (done.files && done.files[0]) || {};
  let permalink = file.permalink;
  if (!permalink && file.id) {
    try {
      const info = await callSlack('files.info', { file: file.id }, token);
      permalink = info.file && info.file.permalink;
    } catch (err) {
      // permalink remains undefined
    }
  }
  return { id: file.id, name, title: file.title, permalink };
}

async function main() {
  const args = process.argv.slice(2);
  if (args.length < 2) {
    console.error(
      'Usage: node upload_file.cjs <channel> <filepath> [--comment "<text>"] [--title "<title>"] [--filename <name>]',
    );
    process.exit(1);
  }
  const channel = args[0];
  const filePath = args[1];
  const opts = {};
  for (let i = 2; i < args.length; i++) {
    const flag = args[i];
    const value = args[i + 1];
    if (value === undefined) {
      console.error(`Failure: missing value for ${flag}`);
      process.exit(1);
    }
    if (flag === '--comment') {
      opts.comment = value;
    } else if (flag === '--title') {
      opts.title = value;
    } else if (flag === '--filename') {
      opts.filename = value;
    } else {
      console.error(`Failure: unknown option ${flag}`);
      process.exit(1);
    }
    i++;
  }
  try {
    const result = await uploadFile({ channel, filePath, ...opts });
    process.stdout.write(
      `Success: uploaded "${result.name}" (id=${result.id}) to ${channel}${result.permalink ? `\nPermalink: ${result.permalink}` : ''}\n`,
    );
  } catch (err) {
    process.stderr.write(`Failure: ${err.slackError || err.message}\n`);
    process.exit(1);
  }
}

module.exports = { uploadFile };

if (require.main === module) {
  main();
}
